import random
import string
from typing import List

# This generator produces valid path-like strings suitable for UCL path lookups.
# It aims to cover dot-notation, array indices, quoted keys, escaped separators,
# custom separators, Unicode, and edge-case path constructs while remaining valid text.

SEPS = [".", "/", ":", "|", ",", ";"]

SAFE_KEY_CHARS = string.ascii_letters + string.digits + "_-"

UNICODE_FRAGMENTS = [
    "ключ",          # Cyrillic
    "键",            # CJK
    "παράδειγμα",   # Greek
    "😀",            # Emoji
    "ñandú",        # Latin-1
]

QUOTABLE_KEYS = [
    "with.dot",           # key containing dot
    "space key",          # space
    "leading-space ",
    " trailing-space",
    "brackets[0]",        # contains brackets
    "quote\"key",        # contains quote
    "hash#key",
]

ARRAY_PATTERNS = [
    "arr[0]",
    "arr[1]",
    "list[10]",
    "nested[2][3]",
]

SPECIAL_KEYS = [
    "0", "00", "01",   # numeric-like keys
    "true", "false",    # boolean-like keys
    "null",              # null-like
    "NaN", "Inf",       # numeric specials
]


def _rand_weighted_choice(r: random.Random, items: List[str], weights: List[int]) -> str:
    total = sum(weights)
    pick = r.randrange(total)
    acc = 0
    for item, w in zip(items, weights):
        acc += w
        if pick < acc:
            return item
    return items[-1]


def _make_simple_key(r: random.Random) -> str:
    # Alnum with optional underscores/dashes, length 1..12
    n = r.randint(1, 12)
    return ''.join(r.choice(SAFE_KEY_CHARS) for _ in range(n))


def _maybe_unicode_key(r: random.Random) -> str:
    if r.random() < 0.25:
        return r.choice(UNICODE_FRAGMENTS)
    return _make_simple_key(r)


def _maybe_special_key(r: random.Random) -> str:
    if r.random() < 0.25:
        return r.choice(SPECIAL_KEYS)
    return _maybe_unicode_key(r)


def _quoted(key: str) -> str:
    # JSON-like quoting for keys that contain separators
    escaped = key.replace('\\', '\\\\').replace('"', '\\"')
    return f'"{escaped}"'


def _maybe_quote_key(r: random.Random, key: str, sep: str) -> str:
    # If key contains sep or space, quote with probability or when necessary
    if sep in key or ' ' in key or '[' in key or ']' in key or key == "":
        return _quoted(key)
    if r.random() < 0.15:
        return _quoted(key)
    return key


def _make_array_suffixes(r: random.Random) -> str:
    # Generate zero or more [index] suffixes
    parts = []
    # 0..2 extra indices
    for _ in range(r.randint(0, 2)):
        idx = r.randint(0, 50)
        parts.append(f"[{idx}]")
    return ''.join(parts)


def _make_fragment(r: random.Random, sep: str) -> str:
    # Weighted selection among patterns
    choice = _rand_weighted_choice(
        r,
        ["simple", "unicode", "special", "quotable", "arrayname", "empty"],
        [40,       10,         10,         10,          25,           5]
    )

    if choice == "simple":
        key = _make_simple_key(r)
    elif choice == "unicode":
        key = r.choice(UNICODE_FRAGMENTS)
    elif choice == "special":
        key = r.choice(SPECIAL_KEYS)
    elif choice == "quotable":
        key = r.choice(QUOTABLE_KEYS)
    elif choice == "arrayname":
        base = _maybe_unicode_key(r)
        key = base + _make_array_suffixes(r)
    else:  # empty
        key = ""

    key = _maybe_quote_key(r, key, sep)

    # Optionally append array indices even if not chosen above
    if r.random() < 0.35 and not key.endswith(']'):
        key += _make_array_suffixes(r)
    return key


def _join_fragments(fragments: List[str], sep: str) -> str:
    if sep == ".":
        return ".".join(fragments)
    return sep.join(fragments)


def _maybe_leading_trailer(r: random.Random, path: str, sep: str) -> str:
    # Occasionally add leading or trailing separators (some implementations may ignore or treat specially)
    if r.random() < 0.15:
        path = sep + path
    if r.random() < 0.15:
        path = path + sep
    return path


def _maybe_escape_sep_in_quoted(r: random.Random, path: str, sep: str) -> str:
    # For quoted keys, ensure we sometimes include the separator inside quotes to test parser behavior
    # Already handled by QUOTABLE_KEYS and quoting; no additional escaping needed for UCL path.
    return path


def _build_path(r: random.Random) -> str:
    # Choose a separator (dot is primary for ucl_object_lookup_path; others for _path_char)
    sep = r.choice(SEPS)

    # Number of fragments: 1..6 (favor 2..4)
    n = _rand_weighted_choice(r, ["1","2","3","4","5","6"], [10, 25, 25, 20, 12, 8])
    n = int(n)

    fragments = [_make_fragment(r, sep) for _ in range(n)]

    # Occasionally insert explicit array index step as its own fragment (e.g., .0 or /3)
    if r.random() < 0.3:
        pos = r.randrange(len(fragments))
        fragments.insert(pos, str(r.randint(0, 20)))

    path = _join_fragments(fragments, sep)
    path = _maybe_leading_trailer(r, path, sep)
    path = _maybe_escape_sep_in_quoted(r, path, sep)

    # For dot separator, sometimes add array syntax directly after a fragment (key[0].sub)
    if sep == '.' and r.random() < 0.4:
        # append indices to a random fragment if not already arrayed
        parts = path.split('.')
        if parts:
            i = r.randrange(len(parts))
            if not parts[i].endswith(']'):
                parts[i] += _make_array_suffixes(r)
            path = '.'.join(parts)

    return path


def generate(seed: int) -> bytes:
    r = random.Random(seed)

    # Decide between crafting for dot-notation (ucl_object_lookup_path) or custom separators
    # Both variants produce a single returned byte buffer; fuzzing harness may reuse it for different stubs.
    # We'll bias slightly towards dot-notation as it is the default API.
    use_dot = r.random() < 0.6

    if use_dot:
        sep = "."
        # Build multiple candidate segments with emphasis on nested object/array addressing
        fragments: List[str] = []
        count = r.randint(1, 6)
        for _ in range(count):
            fragments.append(_make_fragment(r, sep))
        # Sometimes inject pure index fragments like "0"
        if r.random() < 0.3:
            fragments.insert(r.randrange(len(fragments) + 1), str(r.randint(0, 15)))
        path = _join_fragments(fragments, sep)
        # Optionally leading/trailing dot
        path = _maybe_leading_trailer(r, path, sep)
        # Optionally array suffix after random fragment
        if r.random() < 0.4:
            parts = path.split('.')
            if parts:
                i = r.randrange(len(parts))
                if not parts[i].endswith(']'):
                    parts[i] += _make_array_suffixes(r)
                path = '.'.join(parts)
    else:
        path = _build_path(r)

    # Ensure the final buffer is within size constraints
    if len(path.encode('utf-8')) > 4096:
        path = path[:2048]

    return path.encode('utf-8')

import random
import string
from typing import List, Tuple

# Generate valid UCL (Universal Configuration Language) content.
# Goals:
# - Produce syntactically valid inputs for ucl_parser_add_* APIs.
# - Cover objects, arrays, scalars, mixed nesting, comments, macros, includes,
#   variable substitutions, numeric formats, booleans, nulls, times, bytes, and strings
#   with different quoting/escaping.
# - Sometimes produce JSON-only (no comments/macros) for UCL_PARSE_JSON-like handling.
# - Keep size <= 4096 bytes.
# - Deterministic w.r.t. provided seed, yet varied.

MAX_SIZE = 4096

def _rand_ident(r: random.Random, min_len=3, max_len=10) -> str:
    first = r.choice(string.ascii_letters + '_')
    rest = ''.join(r.choice(string.ascii_letters + string.digits + '._-') for _ in range(r.randint(min_len-1, max_len-1)))
    return first + rest

def _rand_string(r: random.Random) -> str:
    # Mix plain, quoted, squoted, multiline, escaped
    kinds = ["plain", "dq", "sq", "multiline", "bytes"]
    kind = r.choice(kinds)
    if kind == "plain":
        # Plain (no spaces, commas, braces)
        chars = string.ascii_letters + string.digits + "._-:/@#"
        val = ''.join(r.choice(chars) for _ in range(r.randint(1, 20)))
        return val
    elif kind == "dq":
        s = ''.join(r.choice(string.ascii_letters + string.digits + " _-:/@#\t") for _ in range(r.randint(0, 25)))
        # Add some escapes
        s = s.replace("\t", "\\t")
        s = s.replace("\"", "\"")
        return '"' + s + '"'
    elif kind == "sq":
        s = ''.join(r.choice(string.ascii_letters + string.digits + " _-:/@#") for _ in range(r.randint(0, 25)))
        s = s.replace("'", "'\''")  # conservative
        return "'" + s + "'"
    elif kind == "multiline":
        # UCL supports multiline with <<EOT ... EOT
        tag = _rand_ident(r, 3, 6)
        lines = []
        for _ in range(r.randint(1, 3)):
            line = ''.join(r.choice(string.ascii_letters + string.digits + " _-:;.,/()[]{}") for _ in range(r.randint(0, 40)))
            lines.append(line)
        return "<<" + tag + "\n" + "\n".join(lines) + "\n" + tag
    else:  # bytes (0x...)
        nbytes = r.randint(1, 8)
        return "0x" + ''.join(r.choice('0123456789abcdef') for _ in range(nbytes * 2))

def _rand_number(r: random.Random) -> str:
    # Cover ints, hex, floats, sci, time suffixes, bytes with units
    choice = r.randint(0, 6)
    if choice == 0:
        return str(r.randint(-2**31, 2**31-1))
    if choice == 1:
        return str(r.uniform(-1e6, 1e6))
    if choice == 2:
        # scientific
        base = r.uniform(1e-6, 1e6)
        exp = r.randint(-10, 10)
        return f"{base:.6e}".replace("e+", "e")
    if choice == 3:
        # hex int
        return hex(r.randint(0, 2**32 - 1))
    if choice == 4:
        # time like 10ms, 2s, 5m, 1h, 1d
        units = ["ms", "s", "m", "h", "d"]
        return f"{r.randint(0, 10000)}{r.choice(units)}"
    if choice == 5:
        # bytes like 10k, 4M, 2G
        units = ["k", "K", "M", "G"]
        return f"{r.randint(0, 1_000_000)}{r.choice(units)}"
    # boolean-like numeric strings
    return str(r.randint(0, 1))

def _rand_boolean(r: random.Random) -> str:
    return r.choice(["true", "false", "yes", "no", "on", "off"])

def _rand_null(r: random.Random) -> str:
    return r.choice(["null", "NULL"])

def _rand_value(r: random.Random, depth: int) -> str:
    kind = r.choices(
        ["string", "number", "bool", "null", "array", "object"],
        weights=[3, 3, 2, 1, 2, 2], k=1
    )[0]
    if depth <= 0 and kind in ("array", "object"):
        kind = r.choice(["string", "number", "bool", "null"])
    if kind == "string":
        return _rand_string(r)
    if kind == "number":
        return _rand_number(r)
    if kind == "bool":
        return _rand_boolean(r)
    if kind == "null":
        return _rand_null(r)
    if kind == "array":
        return _rand_array(r, depth-1)
    return _rand_object(r, depth-1)

def _rand_array(r: random.Random, depth: int) -> str:
    # Mix JSON style [a, b] and UCL implicit arrays: key = val; key = val;
    # Here we emit explicit arrays for portability across stubs.
    n = r.randint(0, 6)
    vals = [_rand_value(r, depth) for _ in range(n)]
    # Occasionally add trailing comma (UCL permits)
    trailing = "," if n > 0 and r.random() < 0.3 else ""
    return "[" + ", ".join(vals) + trailing + "]"

def _rand_kv(r: random.Random, depth: int) -> Tuple[str, str]:
    key_style = r.choice(["bare", "dq", "sq"])
    if key_style == "bare":
        key = _rand_ident(r)
    elif key_style == "dq":
        key = '"' + _rand_ident(r) + '"'
    else:
        key = "'" + _rand_ident(r) + "'"
    val = _rand_value(r, depth)
    sep = ":" if r.random() < 0.5 else " ="
    term = ";" if sep.strip() == "=" and r.random() < 0.8 else ""
    return key + f"{sep} " , val + term

def _rand_object(r: random.Random, depth: int) -> str:
    n = r.randint(0, 8)
    items = []
    for _ in range(n):
        k, v = _rand_kv(r, depth)
        items.append(k + v)
    # Optionally nested block form: key { ... }
    if depth > 0 and r.random() < 0.3:
        blk_key = _rand_ident(r)
        nested = _rand_object(r, depth-1)
        items.append(f"{blk_key} {{ {nested} }}")
    # Mix separators: commas and newlines
    if r.random() < 0.5:
        joiner = ",\n"
    else:
        joiner = "\n"
    body = joiner.join(items)
    if r.random() < 0.5:
        return "{" + ("\n" + body + "\n" if body else "") + "}"
    else:
        # UCL also allows top-level without braces in some contexts; but we keep braces for JSON compatibility
        return "{" + body + "}"

def _rand_comment(r: random.Random) -> str:
    if r.random() < 0.5:
        return "// " + ''.join(r.choice(string.ascii_letters + " ") for _ in range(r.randint(0, 30)))
    else:
        return "/* " + ''.join(r.choice(string.ascii_letters + " ") for _ in range(r.randint(0, 30))) + " */"

def _rand_macro_include(r: random.Random) -> str:
    # UCL macros start with a dot: .include "file"; also .tryinclude, .include_if
    m = r.choice(["include", "tryinclude", "load" , "include_json"])  # implementations vary; include/tryinclude are common
    path = "/" + "/".join(_rand_ident(r,2,6) for _ in range(r.randint(1,3)))
    return f".{m} \"{path}\"\n"

def _rand_variable_use(r: random.Random) -> str:
    # ${VAR} usage
    var = _rand_ident(r).upper()
    default = _rand_string(r) if r.random() < 0.3 else None
    if default is None:
        return f"\"${{{var}}}\""
    else:
        # Some implementations support ${VAR:-default}
        d = default
        if not (d.startswith('"') or d.startswith("'")):
            d = '"' + d + '"'
        return f"\"${{{var}:-{d}}}\""

def _header_block(r: random.Random) -> str:
    parts: List[str] = []
    # Optionally start with comments and macros/includes
    for _ in range(r.randint(0, 2)):
        if r.random() < 0.6:
            parts.append(_rand_comment(r) + "\n")
        if r.random() < 0.5:
            parts.append(_rand_macro_include(r))
    return ''.join(parts)

def _top_level(r: random.Random) -> str:
    # Choose between a single object, array, or a mixed stream of statements (valid UCL)
    mode = r.choices(["object", "array", "mixed", "json_strict"], weights=[4, 2, 3, 2])[0]
    out = _header_block(r)
    if mode == "object":
        out += _rand_object(r, depth=3)
    elif mode == "array":
        out += _rand_array(r, depth=3)
    elif mode == "json_strict":
        # JSON-compatible object without comments/macros/semicolons
        n = r.randint(1, 6)
        pairs = []
        for _ in range(n):
            key = '"' + _rand_ident(r) + '"'
            val_kind = r.choice(["str","num","bool","null","arr","obj"])
            if val_kind == "str":
                val = '"' + ''.join(r.choice(string.ascii_letters + string.digits + " _-:/@#") for _ in range(r.randint(0, 20))) + '"'
            elif val_kind == "num":
                val = _rand_number(r)
            elif val_kind == "bool":
                val = r.choice(["true","false"])
            elif val_kind == "null":
                val = "null"
            elif val_kind == "arr":
                val = _rand_array(r, 2)
            else:
                val = _rand_object(r, 2)
            pairs.append(f"{key}: {val}")
        out += "{" + ", ".join(pairs) + "}"
    else:  # mixed
        stmts: List[str] = []
        # Variable assignments/macros/comments interleaved with key-value
        for _ in range(r.randint(2, 6)):
            choice = r.random()
            if choice < 0.2:
                stmts.append(_rand_comment(r))
            elif choice < 0.35:
                stmts.append(_rand_macro_include(r).rstrip())
            elif choice < 0.5:
                # var usage as a value under a key
                k = _rand_ident(r)
                stmts.append(f"{k} = {_rand_variable_use(r)};")
            else:
                # produce block or plain kv
                if r.random() < 0.4:
                    k = _rand_ident(r)
                    stmts.append(f"{k} {{ {_rand_object(r, 2)} }}")
                else:
                    k, v = _rand_kv(r, 2)
                    stmts.append(k + v)
        out += "\n".join(stmts)
    return out


def generate(seed: int) -> bytes:
    r = random.Random(seed)
    doc = _top_level(r)
    # Ensure length limit; trim gracefully at statement boundary if possible
    data = doc.encode('utf-8', errors='strict')
    if len(data) > MAX_SIZE:
        # Try to cut at last newline before limit
        cut = data.rfind(b"\n", 0, MAX_SIZE)
        if cut == -1:
            data = data[:MAX_SIZE]
        else:
            data = data[:cut]
    # Optionally append a newline to finalize last line (useful for file-based parsing)
    if not data.endswith(b"\n"):
        data += b"\n"
    return data
